#!/usr/bin/env python3\n\"\"\"\nQueen Model VPS Agent - Interactive CLI\nটার্মিনাল থেকে সরাসরি কমান্ড চালান\n\"\"\"\n\nimport sys\nimport os\nfrom queen_model_agent import QueenModelAgent\nfrom secondary_agent_control import AgentManager\n\nclass AgentCLI:\n    def __init__(self):\n        self.queen = QueenModelAgent()\n        self.manager = AgentManager()\n        self.manager.register_agent(\"hybrid_agent\", \"/root/hybrid_agent_project/\")\n        self.manager.register_agent(\"local_models\", \"/root/local/\")\n    \n    def show_menu(self):\n        print(\"\\n\" + \"=\"*60)\n        print(\"🤖 Queen Model VPS Agent CLI\")\n        print(\"=\"*60)\n        print(\"\\n1. Queen Model (Primary Agent)\")\n        print(\"2. Hybrid Agent (Secondary)\")\n        print(\"3. Local Models (Secondary)\")\n        print(\"4. System Status\")\n        print(\"5. List Models\")\n        print(\"6. Run Custom Command\")\n        print(\"7. View Logs\")\n        print(\"8. Exit\")\n        print(\"\\n\" + \"=\"*60)\n    \n    def show_queen_menu(self):\n        print(\"\\n👑 Queen Model Commands:\")\n        print(\"1. Execute Command\")\n        print(\"2. Get System Status\")\n        print(\"3. List Models\")\n        print(\"4. Save Logs\")\n        print(\"5. Back\")\n    \n    def execute_queen(self):\n        while True:\n            self.show_queen_menu()\n            choice = input(\"\\nChoose: \").strip()\n            \n            if choice == \"1\":\n                cmd = input(\"Enter command: \").strip()\n                success, output = self.queen.execute_command(cmd)\n                print(f\"\\nSuccess: {success}\")\n                print(output)\n            elif choice == \"2\":\n                status = self.queen.get_system_status()\n                print(\"\\n📊 System Status:\")\n                for key, value in status.items():\n                    print(f\"  {key}: {value}\")\n            elif choice == \"3\":\n                models = self.queen.list_models()\n                print(\"\\n📦 Available Models:\")\n                for model, info in models.items():\n                    print(f\"  {model}: {info.get('status', 'unknown')}\")\n            elif choice == \"4\":\n                result = self.queen.save_logs()\n                print(result)\n            elif choice == \"5\":\n                break\n            else:\n                print(\"❌ Invalid choice\")\n    \n    def execute_secondary(self, agent_name):\n        cmd = input(f\"Enter command for {agent_name}: \").strip()\n        success, output = self.manager.execute_on_agent(agent_name, cmd)\n        print(f\"\\nSuccess: {success}\")\n        print(output)\n    \n    def run(self):\n        while True:\n            self.show_menu()\n            choice = input(\"Choose: \").strip()\n            \n            if choice == \"1\":\n                self.execute_queen()\n            elif choice == \"2\":\n                self.execute_secondary(\"hybrid_agent\")\n            elif choice == \"3\":\n                self.execute_secondary(\"local_models\")\n            elif choice == \"4\":\n                status = self.queen.get_system_status()\n                print(\"\\n📊 System Status:\")\n                for key, value in status.items():\n                    print(f\"  {key}: {value}\")\n            elif choice == \"5\":\n                models = self.queen.list_models()\n                print(\"\\n📦 Available Models:\")\n                for model, info in models.items():\n                    print(f\"  {model}\")\n                    for k, v in info.items():\n                        print(f\"    {k}: {v}\")\n            elif choice == \"6\":\n                cmd = input(\"Enter command: \").strip()\n                success, output = self.queen.execute_command(cmd)\n                print(f\"\\nSuccess: {success}\")\n                print(output)\n            elif choice == \"7\":\n                result = self.queen.save_logs()\n                print(result)\n                print(f\"\\nTotal commands logged: {len(self.queen.logs)}\")\n            elif choice == \"8\":\n                print(\"\\n👋 Goodbye!\")\n                break\n            else:\n                print(\"❌ Invalid choice\")\n\nif __name__ == \"__main__\":\n    cli = AgentCLI()\n    cli.run()\n